import{_ as s,a0 as i,w as l,s as u,ao as d,I as o,x as a,a1 as e,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"10个有用的Linux命令面试问题及答案 | LCTT x X-CMD","titleTemplate":false,"description":"10个有用的Linux命令面试问题及答案 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"10个有用的Linux命令面试问题及答案 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"10个有用的Linux命令面试问题及答案 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140722 10 Useful Interview Questions and Answers on Linux Commands","title":"10个有用的Linux命令面试问题及答案","tag":"201408","desc":""},"relativePath":"201408/20140722 10 Useful Interview Questions and Answers on Linux Commands.md","filePath":"[post].md"}'),p={name:"201408/20140722 10 Useful Interview Questions and Answers on Linux Commands.md"};function m(x,n,h,f,L,g){const t=i("Link");return l(),u("div",null,[n[13]||(n[13]=d(`<h1 id="_10个有用的linux命令面试问题及答案" tabindex="-1">10个有用的Linux命令面试问题及答案 <a class="header-anchor" href="#_10个有用的linux命令面试问题及答案" aria-label="Permalink to “10个有用的Linux命令面试问题及答案”">​</a></h1><p>Linux命令行，以及用户使用Linux命令进行Linux shell交互，是Linux最吸引人的地方，也是面试中最普遍的话题之一。在这篇文章中，我们将提出10个面试中很重要问题，这肯定能拓宽你的知识面。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Linux-Command-Questions.png" alt="Linux Command Questions"> Linux Command Questions</p><h3 id="_1-如何暂停一个正在运行的进程-让其在后台运行" tabindex="-1">1. 如何暂停一个正在运行的进程，让其在后台运行？ <a class="header-anchor" href="#_1-如何暂停一个正在运行的进程-让其在后台运行" aria-label="Permalink to “1. 如何暂停一个正在运行的进程，让其在后台运行？”">​</a></h3><p><strong>答案</strong>：为了停止正在运行的进程，让其在后台运行，我们可以使用组合键 Ctrl+Z。</p><h3 id="_2-什么是安装linux所需的最小分区数量-以及如何查看系统启动信息" tabindex="-1">2. 什么是安装Linux所需的最小分区数量，以及如何查看系统启动信息？ <a class="header-anchor" href="#_2-什么是安装linux所需的最小分区数量-以及如何查看系统启动信息" aria-label="Permalink to “2. 什么是安装Linux所需的最小分区数量，以及如何查看系统启动信息？”">​</a></h3><p><strong>答案</strong>：单独一个/root分区足以执行所有的系统任务，但是强烈建议安装Linux时，需要至少三个分区：/root,/boot,/swap。一个IDE硬盘驱动器支持高达63个分区，SCSI硬盘驱动器支持超过15个分区。</p><p>为了检查启动信息，我们可以使用cat或者dmesg命令，如下所示：</p><pre><code>#cat /var/log/messages
</code></pre><p>OR</p><pre><code>#dmesg
</code></pre><h3 id="_3-在你的linux机器上跟踪系统事件的守护进程名是什么" tabindex="-1">3. 在你的Linux机器上跟踪系统事件的守护进程名是什么？### <a class="header-anchor" href="#_3-在你的linux机器上跟踪系统事件的守护进程名是什么" aria-label="Permalink to “3. 在你的Linux机器上跟踪系统事件的守护进程名是什么？###”">​</a></h3><p><strong>答案</strong>：&#39;syslogd&#39;，它负责跟踪系统信息，并将跟踪日志存储在特定的日志文件里。</p><h3 id="_4-在-root分区运行-fsck-命令的最低要求是什么" tabindex="-1">4. 在/root分区运行&#39;fsck&#39;命令的最低要求是什么？### <a class="header-anchor" href="#_4-在-root分区运行-fsck-命令的最低要求是什么" aria-label="Permalink to “4. 在/root分区运行&#39;fsck&#39;命令的最低要求是什么？###”">​</a></h3><p><strong>答案</strong>：/root分区必须挂载为只读模式，而不是读写模式</p><h3 id="_5-如何分层复制-home目录到另一个目录" tabindex="-1">5. 如何分层复制/home目录到另一个目录？### <a class="header-anchor" href="#_5-如何分层复制-home目录到另一个目录" aria-label="Permalink to “5. 如何分层复制/home目录到另一个目录？###”">​</a></h3><p><strong>答案</strong>：Linux的&#39;cpio&#39;命令起到了效果。&#39;cpio&#39;可以分层地复制文件和目录层次结构到另一个位置。</p><h3 id="_6-在linux中-怎样实现日志文件的自动替换" tabindex="-1">6. 在Linux中，怎样实现日志文件的自动替换？### <a class="header-anchor" href="#_6-在linux中-怎样实现日志文件的自动替换" aria-label="Permalink to “6. 在Linux中，怎样实现日志文件的自动替换？###”">​</a></h3><p><strong>答案</strong>：&#39;logrotate&#39;提供日志自动替换功能。</p><h3 id="_7-怎样知道linux中是谁在安排工作" tabindex="-1">7. 怎样知道Linux中是谁在安排工作？### <a class="header-anchor" href="#_7-怎样知道linux中是谁在安排工作" aria-label="Permalink to “7. 怎样知道Linux中是谁在安排工作？###”">​</a></h3><p><strong>答案</strong>：使用&#39;at&#39;命令加上&#39;-l&#39;选项，就可以查出。</p><h3 id="_8-如何在不解压tar包的前提下-查看包里的内容" tabindex="-1">8. 如何在不解压tar包的前提下，查看包里的内容？ <a class="header-anchor" href="#_8-如何在不解压tar包的前提下-查看包里的内容" aria-label="Permalink to “8. 如何在不解压tar包的前提下，查看包里的内容？”">​</a></h3><p><strong>答案</strong>：使用&#39;tar -tvf&#39;。选项‘t’(显示内容)，‘v’（详细报告tar处理的文件信息），‘f’（使用档案文件或者设备）</p><h3 id="_9-什么是页面错误-它是怎么发生的" tabindex="-1">9. 什么是页面错误，它是怎么发生的？### <a class="header-anchor" href="#_9-什么是页面错误-它是怎么发生的" aria-label="Permalink to “9. 什么是页面错误，它是怎么发生的？###”">​</a></h3><p><strong>答案</strong>：当一个程序请求内存中不存在的数据时，就会产生页面错误，导致的结果就是程序停止。</p><h3 id="_10-什么是在程序中返回代码" tabindex="-1">10. 什么是在程序中返回代码？### <a class="header-anchor" href="#_10-什么是在程序中返回代码" aria-label="Permalink to “10. 什么是在程序中返回代码？###”">​</a></h3><p><strong>答案</strong>：返回代码是shell的特性。返回代码显示了程序的状态，一个成功的程序执行后返回‘0’，&amp;&amp;可以用来决定那个应用程序先执行。</p><p>好了，文章要结束了。不久以后，我还会在这分享其余有趣文章的，记得和我们保持联系。还有，别忘了在评论栏里面向我们提供您的宝贵意见。</p><hr>`,29)),o("p",null,[n[1]||(n[1]=a("via: ",-1)),e(t,{href:"http://www.tecmint.com/10-useful-interview-questions-and-answers-on-linux-commands/"},{default:r(()=>[...n[0]||(n[0]=[a("http://www.tecmint.com/10-useful-interview-questions-and-answers-on-linux-commands/",-1)])]),_:1})]),o("p",null,[n[3]||(n[3]=a("原文作者：",-1)),e(t,{href:"http://www.tecmint.com/author/avishek/"},{default:r(()=>[...n[2]||(n[2]=[a("Avishek Kumar",-1)])]),_:1})]),o("p",null,[n[6]||(n[6]=a("译者：",-1)),e(t,{href:"https://github.com/su-kaiyao"},{default:r(()=>[...n[4]||(n[4]=[a("su-kaiyao",-1)])]),_:1}),n[7]||(n[7]=a(" 校对：",-1)),e(t,{href:"https://github.com/carolinewuyan"},{default:r(()=>[...n[5]||(n[5]=[a("Caroline",-1)])]),_:1})]),o("p",null,[n[10]||(n[10]=a("本文由 ",-1)),e(t,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...n[8]||(n[8]=[a("LCTT",-1)])]),_:1}),n[11]||(n[11]=a(" 原创翻译，",-1)),e(t,{href:"http://linux.cn/"},{default:r(()=>[...n[9]||(n[9]=[a("Linux中国",-1)])]),_:1}),n[12]||(n[12]=a(" 荣誉推出",-1))])])}const C=s(p,[["render",m]]);export{b as __pageData,C as default};
